using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 public static partial class ForestSeatingAuthoring {
  const string Forest500Request="Logs/Forest500CloudFade.request",Forest500Logs="Logs/Forest500CloudFade";
  static string Forest500Hash(string path){using(var sha=System.Security.Cryptography.SHA256.Create())return Convert.ToBase64String(sha.ComputeHash(File.ReadAllBytes(path)));}
  static bool LimitedWood(CatalogPlacement p){int i=int.Parse(p.assetId.Substring(p.assetId.Length-2));return i>=21||i>=17&&i<=19;}
  static bool InsideWoodRadius(Geometry d,Vector3 pos,Quaternion rot,Vector3 scale){if(XZ(pos).magnitude>200)return false;var b=WorldBounds(d,pos,rot,scale);for(int i=0;i<4;i++)if(new Vector2((i&1)==0?b.min.x:b.max.x,(i&2)==0?b.min.z:b.max.z).magnitude>200)return false;return true;}
  [InitializeOnLoadMethod]static void Register500(){EditorApplication.update+=Pending500;}
  static void Pending500(){if(!File.Exists(Forest500Request)||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete(Forest500Request);try{Apply500();}catch(Exception e){Directory.CreateDirectory(Forest500Logs);File.WriteAllText(Forest500Logs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  [MenuItem("Snowglow/Environment/Use 500 forest objects, 200m wood and fading clouds")]
  public static void Apply500(){
   var scene=SceneManager.GetActiveScene();Require(scene.path==SceneValidation.ScenePath&&!EditorApplication.isPlayingOrWillChangePlaymode,"open Pinefall stopped");Directory.CreateDirectory(Forest500Logs);if(!File.Exists(Forest500Logs+"/Pinefall-before.unity"))Require(EditorSceneManager.SaveScene(scene,Forest500Logs+"/Pinefall-before.unity",true),"backup");if(scene.isDirty)EditorSceneManager.SaveScene(scene,Forest500Logs+"/Pinefall-unsaved-before.unity",true);cache.Clear();outerIds.Clear();slopeIds.Clear();
   var forest=All<CatalogPlacement>(scene).Where(Tree).OrderBy(p=>p.placementId).ToList();Require(forest.Count==638||forest.Count==500,"expected current 638 or finished 500 population");var terrain=All<Terrain>(scene).Single();var session=All<PrototypeSession>(scene).Single();var wind=All<CloudWindController>(scene).Single();var sunSeed=session.Snow.seed;string snow=SnowData(sunSeed);var nonforest=All<CatalogPlacement>(scene).Where(p=>!Tree(p)&&!string.IsNullOrEmpty(p.placementId)).ToDictionary(p=>p.placementId,FullPose);var fleet=session.Fleet.Select(m=>m.transform.localToWorldMatrix.ToString("R")).ToArray();var identities=forest.ToDictionary(p=>p.placementId,p=>p.assetId+"|"+p.transform.localScale.ToString("R"));
   var protectedPaths=All<MeshFilter>(scene).Where(f=>f.sharedMesh).Select(f=>AssetDatabase.GetAssetPath(f.sharedMesh)).Concat(new[]{AssetDatabase.GetAssetPath(terrain.terrainData),AssetDatabase.GetAssetPath(sunSeed),"Assets/Snowglow/Catalog/Sources/ForestAlphaCards/ForestCards.mat"}).Where(p=>p.StartsWith("Assets/")).Distinct().ToDictionary(p=>p,p=>Forest500Hash(p));
   var protectedGaps=new HashSet<string>();if(File.Exists("Logs/ForestGaps/Relocations.csv"))foreach(var line in File.ReadAllLines("Logs/ForestGaps/Relocations.csv").Skip(1))protectedGaps.Add(line.Split(',')[0]);var centres=forest.ToDictionary(p=>p.placementId,p=>WorldBounds(Data(p.assetId),p.transform.position,p.transform.rotation,p.transform.lossyScale).center);var survivors=new List<CatalogPlacement>(forest);var removed=new List<CatalogPlacement>();
   while(survivors.Count>500){var candidates=survivors.Where(p=>!LimitedWood(p)&&!protectedGaps.Contains(p.placementId)&&survivors.Count(q=>q.assetId==p.assetId)>3).Select(p=>new{p,near=survivors.Where(q=>q!=p&&!LimitedWood(q)).Min(q=>Vector2.Distance(XZ(centres[p.placementId]),XZ(centres[q.placementId]))),neighbours=survivors.Count(q=>q!=p&&!LimitedWood(q)&&Vector2.Distance(XZ(centres[p.placementId]),XZ(centres[q.placementId]))<32)}).OrderByDescending(x=>x.neighbours*.25f+(XZ(centres[x.p.placementId]).magnitude>295?2:0)+(HillBand(terrain,x.p.transform.position)==2?1:0)-x.near*.18f).ToArray();Require(candidates.Length>0,"cannot thin while retaining all variants/gap placements");var choice=candidates[0].p;survivors.Remove(choice);removed.Add(choice);}
   var mountains=All<CatalogPlacement>(scene).Where(Mountain).Select(p=>{var rs=p.GetComponentsInChildren<Renderer>(true);var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);return b;}).ToArray();var obstacles=All<Collider>(scene).Where(c=>c.enabled&&c.gameObject.activeInHierarchy&&!c.isTrigger&&!(c is TerrainCollider)&&!(c is MeshCollider&&c.GetComponentInParent<SnowField>())&&!Tree(c.GetComponentInParent<CatalogPlacement>())).Select(c=>c.bounds).ToArray();
   var moving=survivors.Where(p=>LimitedWood(p)&&!InsideWoodRadius(Data(p.assetId),p.transform.position,p.transform.rotation,p.transform.lossyScale)).ToArray();var occupied=survivors.Except(moving).Select(p=>new Occupied{id=p.placementId,point=p.transform.position,radius=Radius(Data(p.assetId),p.transform.lossyScale)}).ToList();var plans=new List<Plan>();var rng=new System.Random(50020012);
   foreach(var tree in moving){var d=Data(tree.assetId);var scale=tree.transform.lossyScale;Plan plan=null;for(int attempt=0;attempt<50000;attempt++){Vector3 point;if(attempt<500){var towards=tree.transform.position;towards.y=0;towards=towards.normalized*175;point=towards+new Vector3((float)rng.NextDouble()*80-40,0,(float)rng.NextDouble()*80-40);}else point=new Vector3((float)rng.NextDouble()*390-195,0,(float)rng.NextDouble()*390-195);if(XZ(point).magnitude>198||Mathf.Abs(point.x)<135&&Mathf.Abs(point.z)<135||!Spaced(d,point,scale,occupied))continue;float yaw=attempt==0?Yaw(tree.transform.rotation):(float)rng.NextDouble()*360;if(!Fit(d,terrain,point,yaw,scale,mountains,obstacles,out var pos,out var rot)||!InsideWoodRadius(d,pos,rot,scale))continue;plan=new Plan{existing=tree,geometry=d,id=tree.placementId,position=pos,rotation=rot,scale=scale,oldPosition=tree.transform.position};break;}Require(plan!=null,"no safe 200m wood site: "+tree.placementId);plans.Add(plan);occupied.Add(new Occupied{id=plan.id,point=plan.position,radius=Radius(d,plan.scale)});}
   // Complete plans and cloud checks before altering the forest.
   CloudFadeAuthoring.Apply(wind);string fade=CloudFadeAuthoring.Tests(wind);var oldBounds=removed.Concat(moving).SelectMany(p=>p.GetComponentsInChildren<Collider>(true)).Select(c=>c.bounds).ToArray();var removedIds=removed.Select(p=>p.placementId).ToArray();var removedVariants=removed.Select(p=>p.assetId).ToArray();
   Undo.IncrementCurrentGroup();int undo=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("500 forest objects and 200m wood");bool saved=false;
   try{foreach(var p in removed)Undo.DestroyObjectImmediate(p.gameObject);foreach(var p in plans){Undo.RecordObject(p.existing.transform,"Relocated wood");p.existing.transform.SetPositionAndRotation(p.position,p.rotation);PrefabUtility.RecordPrefabInstancePropertyModifications(p.existing.transform);}Physics.SyncTransforms();var current=All<CatalogPlacement>(scene).Where(Tree).ToArray();Validate500(current,terrain,mountains);Undo.RecordObject(session.Snow,"Updated wood obstacles");int mask=RefreshMask(session.Snow,oldBounds,current.Where(p=>moving.Any(m=>m==p)).SelectMany(p=>p.GetComponentsInChildren<Collider>(true)).Select(c=>c.bounds).ToArray());Require(snow==SnowData(session.Snow.seed),"snow quantities changed");SceneValidation.Validate(scene);MechanicsChecks.Run();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);Require(EditorSceneManager.SaveScene(scene),"save failed");saved=true;Undo.CollapseUndoOperations(undo);scene=EditorSceneManager.OpenScene(SceneValidation.ScenePath);current=All<CatalogPlacement>(scene).Where(Tree).ToArray();terrain=All<Terrain>(scene).Single();session=All<PrototypeSession>(scene).Single();Validate500(current,terrain,mountains);foreach(var p in current)Require(identities[p.placementId]==p.assetId+"|"+p.transform.localScale.ToString("R"),"identity/local scale changed");foreach(var p in All<CatalogPlacement>(scene).Where(p=>nonforest.ContainsKey(p.placementId??"")))Require(nonforest[p.placementId]==FullPose(p),"nonforest/cloud pose moved");Require(fleet.SequenceEqual(session.Fleet.Select(m=>m.transform.localToWorldMatrix.ToString("R"))),"fleet moved");foreach(var pair in protectedPaths)Require(pair.Value==Forest500Hash(pair.Key),"source changed "+pair.Key);Require(snow==SnowData(session.Snow.seed),"saved snow quantities changed");Require(All<CloudWindController>(scene).Single().fadeSeconds==12,"fade not saved");SceneValidation.Validate(scene);MechanicsChecks.Run();GapOverview(scene,"Forest500.png");File.Copy(GapsLogs+"/Forest500.png",Forest500Logs+"/Forest500.png",true);ForestCardsSceneReview.Run();EditorSceneManager.OpenScene(SceneValidation.ScenePath);
    File.WriteAllLines(Forest500Logs+"/Removed.csv",new[]{"id,variant"}.Concat(removedIds.Select((id,i)=>id+","+removedVariants[i])));File.WriteAllLines(Forest500Logs+"/WoodRelocations.csv",new[]{"id,variant,x,y,z"}.Concat(plans.Select(p=>p.id+","+p.geometry.asset.id+","+p.position.x+","+p.position.y+","+p.position.z)));
    File.WriteAllText(Forest500Logs+"/Validation.txt","PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+". Saved/reopened 500 total forest objects: "+current.Count(p=>!LimitedWood(p))+" leafy/sapling trees and "+current.Count(LimitedWood)+" dead trunks/snags/stumps/logs. Removed "+removedIds.Length+" trees from denser patches; protected recent gap-fill IDs; all 26 variants retained. Moved "+plans.Count+" wood/trunk placements inside 200m root/full-bound radius; other trees retain 330m envelope. Full seating, mountain/town clearance, slope rotation, LOD3, single boxes and 200m/2km card policy checked. Scene validation and 19 snow checks passed. Original meshes/Terrain/snow seed, forest material, retained variants/scales, nonforest/cloud/fleet poses and snow quantities preserved. Obstacle flags reconciled "+mask+" in separate seed if needed. "+fade+" Shared transparent fog-free cloud material; no runtime material/mesh creation or new raycasts. Native forest/gameplay/fade previews generated. Android packaging, live driving and phone performance untested.");
   }catch{if(!saved)Undo.RevertAllDownToGroup(undo);throw;}
  }
  static void Validate500(CatalogPlacement[] forest,Terrain terrain,Bounds[] mountains){Require(forest.Length==500,"population not 500");Validate(forest,terrain,mountains,500);Require(forest.Select(p=>p.assetId).Distinct().Count()==26,"variant lost");foreach(var p in forest){if(LimitedWood(p))Require(InsideWoodRadius(Data(p.assetId),p.transform.position,p.transform.rotation,p.transform.lossyScale),"wood beyond 200m "+p.placementId);var v=p.GetComponent<DistanceVisibility>();Require(v&&v.distance==200&&v.distantDistance==2000&&v.switchBuffer==12,"card policy changed");Require(p.GetComponentsInChildren<Collider>(true).Count(c=>c.enabled&&!c.isTrigger)==1,"single solid collider");}}
 }
}
